.none => {
return null;
},
}
}

pub fn writeMiss(req: AnyRequest, resp: AnyResponse) void {
        _ = req.setYield(false);
        _ = writeAnyStatus(resp, 404);
        _ = resp.writeMark();
        _ = resp.end("", resp.shouldCloseConnection());
}

pub fn buildSlashRedirect(url: []const u8, out: []u8) usize {
        const pq = pathAndQuery(url);
        const path = pq.path;
        const query = pq.query;
        _ = bun.debugAssert((((path.len > 0) and (path[0] == 47)) and ((path.len < 2) or (path[1] != 47))));
        if ((path.len >= out.len)) {
            return 0;
        }
        _ = @memcpy(out[0..path.len], path);
        out[cp_cast_int(usize, path.len)] = 47;
        const q = @min(query.len, ((out.len - path.len) - 1));
        _ = @memcpy(out[(path.len + 1)..((path.len + 1) + q)], query[0..q]);
        return ((path.len + 1) + q);
}

pub fn pathAndQuery(url: []const u8) PathAndQuery {
        var path: []const u8 = url;
        _ = &path;
        var query: []const u8 = "";
        _ = &query;
        if (strings.indexOfChar(url, 63)) |i| {
            _ = &i;
            path = url[0..i];
            query = url[i..];
        }
        if (((path.len > 0) and (path[0] != 47))) {
            const skip: usize = (if (strings.hasPrefixComptimeType(u8, path, "http://")) 7 else (if (strings.hasPrefixComptimeType(u8, path, "https://")) 8 else 0));
            if ((skip > 0)) {
                if (strings.indexOfChar(path[skip..], 47)) |i| {
                    _ = &i;
                    path = path[(skip + i)..];
                } else {
                    path = "/";
                }
            }
        }
        return PathAndQuery{ .path = path, .query = query };
}

pub fn isUrlPathLiteral(b: u8) bool {
        return (std.ascii.isAlphanumeric(b) or (switch (b) {
'-', '.', '_', '~', '!', '$', '&', '\'', '(', ')', '*', '+', ',', ';', '=', ':', '@' => true,
else => false,
}));
}

pub fn resolveSubpath(url: []const u8, url_prefix: []const u8, out: []u8) ?SubpathParts {
        const pq = pathAndQuery(url);
        const path = pq.path;
        var after_prefix: []const u8 = "";
        _ = &after_prefix;
        if (strings.startsWith(path, url_prefix)) {
            after_prefix = path[url_prefix.len..];
        } else {
            if ((((path.len + 1) == url_prefix.len) and std.mem.eql(u8, path, url_prefix[0..(url_prefix.len - 1)]))) {
                after_prefix = "";
            } else {
                return null;
            }
        }
        const overhead = "/index.html\x00".len;
        if (((out.len <= overhead) or (after_prefix.len >= (out.len - overhead)))) {
            return null;
        }
        var raw_slashes: usize = 0;
        _ = &raw_slashes;
        var i: usize = 0;
        _ = &i;
        while ((i < after_prefix.len)) {
            switch (after_prefix[@as(usize, @intCast(i))]) {
'/' => {
raw_slashes = (raw_slashes + 1);
            i = (i + 1);
},
'%' => {
if (((((i + 2) < after_prefix.len) and strings.isASCIIHexDigit(after_prefix[@as(usize, @intCast((i + 1)))])) and strings.isASCIIHexDigit(after_prefix[@as(usize, @intCast((i + 2)))]))) {
                const b = (cp_shl(strings.toASCIIHexValue(after_prefix[@as(usize, @intCast((i + 1)))]), 4) | strings.toASCIIHexValue(after_prefix[@as(usize, @intCast((i + 2)))]));
                if (isUrlPathLiteral(b)) {
                    return null;
                }
                i = (i + 3);
            } else {
                i = (i + 1);
            }
},
else => {
i = (i + 1);
},
}
        }
        var stream = std.io.fixedBufferStream(out[0..after_prefix.len]);
        _ = &stream;
        const writer = stream.writer();
        const decoded_len = (blk_catch_4: { break :blk_catch_4 ((bun.url_mod.PercentEncoding.decode(@TypeOf(writer), writer, after_prefix)) catch |__ce_4| { _ = &__ce_4; return null; }); });
        const decoded = out[0..decoded_len];
        if ((strings.countChar(decoded, 47) != raw_slashes)) {
            return null;
        }
        if ((decoded_len == 0)) {
            return SubpathParts{ .len = 0, .had_trailing_slash = false };
        }
        const had_trailing_slash = (decoded[@as(usize, @intCast((decoded_len - 1)))] == 47);
        const end = (decoded_len - @intFromBool(had_trailing_slash));
        var seg_start: usize = 0;
        _ = &seg_start;
        var j: usize = 0;
        _ = &j;
        while ((j <= end)) : (j = (j + 1)) {
            if (((j == end) or (decoded[@as(usize, @intCast(j))] == 47))) {
                const seg = decoded[seg_start..j];
                if ((((seg.len == 0) or std.mem.eql(u8, seg, ".")) or std.mem.eql(u8, seg, ".."))) {
                    return null;
                }
                seg_start = (j + 1);
            } else {
                if ((((decoded[@as(usize, @intCast(j))] == 0) or (decoded[@as(usize, @intCast(j))] == 92)) or (decoded[@as(usize, @intCast(j))] == 58))) {
                    return null;
                }
            }
        }
        return SubpathParts{ .len = end, .had_trailing_slash = had_trailing_slash };
}

pub fn formatWeakEtag(buf: *[40]u8, size: u64, mtime_ms: u64) []const u8 {
        return ((std.fmt.bufPrint(buf, "W/\"{x}-{x}\"", .{ size, (mtime_ms / 1000) })) catch unreachable);
}

pub fn extensionForMime(path: []const u8) []const u8 {
        const ext = std.fs.path.extension(path);
        if (((ext.len > 0) and (ext[0] == 46))) {
            return ext[1..];
        }
        return ext;
}
